const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{
const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.clock.install();await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);
const mock=()=>{window.spoken=[];window.speak=s=>{if(s)spoken.push(s);return Promise.resolve()};window.tone=()=>{}};await p.evaluate(mock);await p.click('#learningTab');fs.mkdirSync('audit-screenshots',{recursive:true});
await p.evaluate(()=>{const j=DEUTSCH_JOURNEY,g=DEUTSCH_GREETINGS;for(const p of g.phrases)if(recordedAudioFiles(p[0])?.length!==1)throw Error('Missing original recording '+p[0]);if(j.route().length!==9)throw Error('First route size changed');const oldG=JSON.stringify({version:2,passed:true,best:8,last:8,attempts:1}),oldC=JSON.stringify({version:2,passed:true,best:8,last:8,attempts:1}),oldV=JSON.stringify({version:1,lessons:{0:{passed:true,best:100},5:{passed:true,best:83}},final:{passed:true,best:100}});profileStorage.setItem(g.key,oldG);profileStorage.setItem(g.courtesyKey,oldC);profileStorage.setItem('deutsch16_journey_village_v1',oldV);j.map();if(!j.route()[0].perfect||profileStorage.getItem(g.key)!==oldG)throw Error('Ship result lost or rewritten');j.select(1);const r=j.route();if(r.length!==7||r[0].id!=='courtesy'||!r[0].perfect||r[1].id!==0||!r[1].earned||r[6].id!==5||!r[6].earned||!j.load().final.passed||profileStorage.getItem(g.courtesyKey)!==oldC||profileStorage.getItem(j.key)!==oldV)throw Error('Relocation shifted or erased old progress');profileStorage.removeItem(g.key);profileStorage.removeItem(g.courtesyKey);profileStorage.removeItem(j.key);j.select(0);if(DEUTSCH_PROGRESS.snapshot().answers!==0)throw Error('Reading results counted study');});
const mapCheck=async(id)=>{await p.evaluate(id=>DEUTSCH_JOURNEY.select(id),id);for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});await p.locator('#learningView img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));await p.evaluate(id=>{const board=document.querySelector('.expedition-board'),nodes=[...document.querySelectorAll('.expedition-pins>.journey-stop')],ys=nodes.map(n=>n.getBoundingClientRect().top);if(nodes.length!==(id?7:9)||ys.some((y,i)=>i&&y<=ys[i-1]))throw Error('Wrong route count/order');const ship=document.querySelector('[data-route-lesson] .expedition-pin-number').getBoundingClientRect(),land=document.querySelector('[data-journey-lesson="0"] .expedition-pin-number').getBoundingClientRect();if((land.top-ship.top)/board.getBoundingClientRect().height>.17)throw Error('Introductory stop too far from island');if(document.querySelector('[data-route-lesson] .expedition-pin-number').getBoundingClientRect().top<board.getBoundingClientRect().top)throw Error('Entry number clipped');if(document.documentElement.scrollWidth>innerWidth+1)throw Error('Route overflow')},id);if(width===390)await p.screenshot({path:'audit-screenshots/arrival-route-'+id+'.png',fullPage:true});}};
await mapCheck(0);await mapCheck(1);await p.evaluate(()=>DEUTSCH_JOURNEY.select(0));await p.click('#alStart');if(await p.locator('.al-word').count()!==6||await p.locator('[data-ship-part]').count()||await p.locator('#learningView').textContent().then(s=>/Danke!|Bitte!|частина|part 1/.test(s)))throw Error('Courtesy/parts remain aboard ship');await p.locator('[data-greeting-audio="0"]').click();if(!await p.evaluate(()=>spoken.at(-1)==='Hallo!'))throw Error('Greeting playback failed');

async function finishTraining(){await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE;while(!a.snapshot().finished){const s=a.snapshot(),q=s.queue[s.index];a.answer(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}})}
async function solveTest(correct=true){await p.evaluate(correct=>{const a=DEUTSCH_ADAPTIVE;if(a.snapshot().lessonMode!=='test'||a.snapshot().queue.length!==18)throw Error('Not a separate 18-task test');while(!a.snapshot().finished){const s=a.snapshot(),q=s.queue[s.index];a.answer(correct?(q.type==='ua'||q.type==='listen'?q.c.ua:q.c.de):'wrong');document.querySelector('#alNext').click()}},correct)}
await p.click('#greetingBegin');if(!await p.evaluate(()=>DEUTSCH_ADAPTIVE.snapshot().queue.length===30&&DEUTSCH_ADAPTIVE.snapshot().queue.every(q=>!q.assessment)))throw Error('Ship training not a full cycle');await finishTraining();if(await p.evaluate(()=>DEUTSCH_GREETINGS.read()))throw Error('Training awarded ship seal');await p.click('#alStartTest');await solveTest(false);if(await p.evaluate(()=>DEUTSCH_GREETINGS.read().passed))throw Error('Failed ship test passed');await p.click('#greetingRetry');if(await p.locator('#greetingTest').isDisabled())throw Error('Training unlock lost');await p.click('#greetingTest');await solveTest();if(!await p.evaluate(()=>DEUTSCH_GREETINGS.read().lastCorrect===18&&DEUTSCH_GREETINGS.read().assessmentCount===18&&DEUTSCH_GREETINGS.shipState().perfect))throw Error('Ship assessment/mastery failed');await p.click('#greetingContinue');if(!await p.evaluate(()=>DEUTSCH_JOURNEY.island===0&&DEUTSCH_ADAPTIVE.snapshot().journey.index===0&&!DEUTSCH_GREETINGS.readCourtesy()))throw Error('Ship handoff failed');await p.evaluate(()=>{const j=DEUTSCH_JOURNEY;j.open(1);if(/Danke!|Bitte!/.test(document.querySelector('#learningView').textContent))throw Error('Courtesy leaked into camp');if(j.queue(0,true).length!==27||j.queue(0,true).some(x=>x.c.group==='courtesy'))throw Error('First final changed');j.select(1)});await p.click('#alStart');if(await p.locator('[data-ship-chapter="courtesy"]').count()!==1||await p.locator('.al-word').count()!==6)throw Error('Courtesy introduction missing');await p.click('#greetingBegin');await finishTraining();if(await p.evaluate(()=>DEUTSCH_GREETINGS.readCourtesy()))throw Error('Training awarded arrival seal');await p.click('#alStartTest');await solveTest();if(!await p.evaluate(()=>DEUTSCH_GREETINGS.readCourtesy().best===8&&DEUTSCH_GREETINGS.readCourtesy().assessmentCount===18))throw Error('Courtesy test failed');await p.click('#greetingContinue');if(!await p.evaluate(()=>DEUTSCH_JOURNEY.island===1&&DEUTSCH_ADAPTIVE.snapshot().journey.index===0))throw Error('Courtesy handoff');await p.evaluate(()=>{const j=DEUTSCH_JOURNEY;j.map();if(!document.querySelector('[data-route-lesson="courtesy"]').closest('.is-perfect')||document.querySelectorAll('[data-expedition-seal]').length!==7)throw Error('Arrival route seal lost');if(j.queue(0,true).length!==21)throw Error('Second final changed');j.courtesy()});await p.click('#greetingTest');await solveTest(false);if(!await p.evaluate(()=>DEUTSCH_GREETINGS.readCourtesy().passed&&DEUTSCH_GREETINGS.readCourtesy().best===8))throw Error('Failed replay erased result');await p.evaluate(()=>{DEUTSCH_JOURNEY.open(2);if(!document.querySelector('[data-polite-later]'))throw Error('Advanced word moved');DEUTSCH_JOURNEY.map()});await p.reload();await p.evaluate(mock);await p.click('#learningTab');if(!await p.locator('[data-route-lesson="courtesy"]').getAttribute('aria-label').then(s=>s.includes('Тест складено')))throw Error('Result lost on reload');await p.evaluate(()=>{document.documentElement.lang='en';DEUTSCH_JOURNEY.courtesy()});if(!await p.locator('#learningView h1').textContent().then(s=>s.includes('Meeting the residents')))throw Error('English missing');await p.click('#profileButton');await p.fill('#profileAddInput','Arrival child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);await p.click('#learningTab');if(await p.evaluate(()=>DEUTSCH_GREETINGS.read()||DEUTSCH_GREETINGS.readCourtesy()))throw Error('Entry results leaked');if(errors.length)throw Error(errors.join(';'));console.log('PASS greeting/courtesy study, full training and separate 18-task exams, legacy rewards, compact routes, original recordings, unchanged island finals, replay/reload and profiles');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
